  async function share(id,commentId=null){const w=await getWhisper(id);if(!w){toast('This Whisper is unavailable.','error');return}const url=`${location.origin}${location.pathname}#whisper/${encodeURIComponent(id)}${commentId?'?comment='+encodeURIComponent(commentId):''}`;const author=w.identity_mode==='anonymous'?'Anonymous':w.author_id===user?.id?profileName():(w.author_profile?.display_name||w.author_profile?.username||'Someone');const text=commentId?'A reply on mindRID':'Reflection shared on mindRID';toast('Preparing share…');try{if(typeof navigator.share==='function'){await navigator.share({title:'mindRID',text,url});toast('Share completed.');return}}catch(e){if(e?.name==='AbortError'){toast('Share cancelled.');return}}try{if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(url);toast('Link copied.')}else{const ta=document.createElement('textarea');ta.value=url;ta.style.position='fixed';ta.style.opacity='0';document.body.appendChild(ta);ta.focus();ta.select();const ok=document.execCommand('copy');ta.remove();if(!ok)throw new Error('Copy is not available.');toast('Link copied.')}}catch(e){toast('Share link: '+url,'error')}}
  function mediaPreview(media,mode='display'){if(!media?.length)return'';return `<div class="media-grid">${media.map(m=>{const src=esc(m.public_url);const meta=`data-src="${src}" data-mime="${esc(m.mime_type||'')}" data-name="${esc(m.file_name||'Attachment')}"`;if(m.mime_type?.startsWith('image/'))return `<button type="button" class="media-tile media-image" data-action="media-open" ${meta} onclick="event.stopPropagation()"><img src="${src}" alt="Attached media" loading="lazy"><span>Expand</span></button>`;if(m.mime_type?.startsWith('video/'))return `<div class="media-tile media-video"><video controls preload="metadata" src="${src}"></video><button type="button" class="media-expand" data-action="media-open" ${meta}>Expand</button></div>`;if(m.mime_type?.startsWith('audio/'))return `<div class="media-tile"><audio controls src="${src}"></audio><button type="button" class="media-expand" data-action="media-open" ${meta}>Open</button></div>`;return `<a class="media-file" href="${src}" target="_blank" rel="noopener">${esc(m.file_name||'Open attachment')}</a>`}).join('')}</div>`}
  function activeComposerRoot(){return document.querySelector('#modal:not(.hidden) .composer')||document.querySelector('.composer')}
  function composerEl(selector){return activeComposerRoot()?.querySelector(selector)||null}
  function attachmentPicker(prefix){return `<div class="attachment-row"><label class="attach-btn"><input id="${prefix}Media" type="file" accept="image/*,video/*,audio/*" multiple hidden>＋ Media</label><span id="${prefix}MediaStatus" class="hint">Choose media · remove any item before posting</span></div><div id="${prefix}MediaPreview"></div>`}
  function bindMediaPicker(prefix,root=activeComposerRoot()){const input=root?.querySelector('#'+prefix+'Media'),preview=root?.querySelector('#'+prefix+'MediaPreview'),status=root?.querySelector('#'+prefix+'MediaStatus');if(!input||input.dataset.bound)return;input.dataset.bound='1';input.addEventListener('change',()=>{const files=[...(input.files||[])];preview.innerHTML=files.map((f,i)=>`<div class="pending-media" data-pending-index="${i}"><span class="pending-media-name">${esc(f.name)}</span><span class="hint">${Math.max(1,Math.round(f.size/1024))} KB</span><button type="button" class="action danger-text" data-action="remove-selected-media" data-prefix="${esc(prefix)}" data-index="${i}">Remove</button></div>`).join('');if(status)status.textContent=files.length?`${files.length} media item${files.length===1?'':'s'} selected.`:'Choose media · remove any item before posting'});}
  function removeSelectedMedia(prefix,index){const input=activeComposerRoot()?.querySelector('#'+prefix+'Media')||document.querySelector('#'+prefix+'Media');if(!input)return;const files=[...(input.files||[])];files.splice(Number(index),1);const dt=new DataTransfer();files.forEach(f=>dt.items.add(f));input.files=dt.files;input.dispatchEvent(new Event('change',{bubbles:true}));}
  async function prepareFiles(input,prefix){const root=input?.closest('.composer')||activeComposerRoot();const status=root?.querySelector('#'+prefix+'MediaStatus'),preview=root?.querySelector('#'+prefix+'MediaPreview');const files=[...(input?.files||[])];if(!files.length)return[];if(!client||!user)throw new Error('Sign in to attach media.');const out=[];try{if(status)status.textContent=`Uploading ${files.length} media item${files.length===1?'':'s'}…`;let done=0;const uploaded=await Promise.all(files.map(async f=>{const m=await uploadMedia(f);out.push(m);done++;if(status)status.textContent=`Uploading ${done} of ${files.length}…`;return m}));if(preview)preview.innerHTML=mediaPreview(out);if(status)status.textContent=`${out.length} media item${out.length===1?'':'s'} attached.`;return out}catch(e){await removeUploadedMedia(out);if(status)status.textContent='Media upload failed. Nothing was posted.';throw e}}
  function composer(){return `<section class="composer"><div class="composer-top"><div class="avatar">${avatarMarkup(currentProfile,profileName())}</div><div style="flex:1"><div class="mention-wrap"><textarea id="whisperText" maxlength="10000" placeholder="What’s going through your mind?"></textarea><div id="whisperMentionSuggestions" class="suggestions"></div></div>${attachmentPicker('whisper')}<div class="tag-editor"><input id="tagLocation" placeholder="📍 Location"><input id="tagFeeling" placeholder="❤️ Feeling"><input id="tagIdea" placeholder="💡 Idea"><input id="tagVibe" placeholder="✨ Vibe"></div><div class="composer-bottom"><div class="composer-controls"><select id="identity" class="select" aria-label="Post identity"><option value="anonymous">Anonymous</option><option value="real">Me</option></select><select id="visibility" class="select" aria-label="Post visibility"><option value="public">Public</option><option value="selected">People I choose</option><option value="private">Private</option></select></div><button class="btn" data-action="save">WHISPER</button></div><div class="hint" style="margin-top:8px">Tag the context of a reflection so mindRID can connect related ideas, feelings and experiences.</div><div id="recipientBox" class="recipient-box hidden"><label>Recipients</label><input id="recipientNames" placeholder="Usernames, separated by commas"><div class="hint">Selected people will be able to see this Whisper.</div></div></div></div></section>`}
  async function resolveRecipients(){const box=composerEl('#recipientBox');if(!box||box.classList.contains('hidden'))return[];const names=(composerEl('#recipientNames')?.value||'').split(',').map(x=>x.trim().toLowerCase()).filter(Boolean);if(!names.length)throw new Error('Choose at least one recipient for a selected Whisper.');const{data,error}=await client.from('profiles').select('id,username').in('username',names);if(error)throw error;const found=(data||[]);const missing=names.filter(n=>!found.some(x=>x.username===n));if(missing.length)throw new Error(`Could not find: ${missing.join(', ')}`);return found.map(x=>x.id)}
  function card(w,media=[]){const anonymous=w.identity_mode!=='real';const name=anonymous?'Anonymous':(w.author_id===user?.id?profileName():(w.author_profile?.display_name||w.author_profile?.username||'Someone'));const mine=w.author_id===user?.id;return `<article class="whisper" data-action="open" data-id="${esc(w.id)}"><div class="avatar">${anonymous?'A':esc((name[0]||'S').toUpperCase())}</div><div class="whisper-main"><div class="whisper-meta"><span class="name">${esc(name)}</span><span class="time">· ${fmt(w.created_at)}${w.updated_at&&w.updated_at!==w.created_at?' · edited':''}</span></div><div class="whisper-body">${esc(w.body)}</div><div class="tag-row" id="tags-${esc(w.id)}"></div><div class="media-slot" id="media-${esc(w.id)}">${mediaPreview(media)}</div><div class="whisper-actions"><button class="action" data-action="like" data-id="${esc(w.id)}" onclick="event.stopPropagation()">♡ Like</button><button class="action" data-action="open" data-id="${esc(w.id)}" onclick="event.stopPropagation()">💬 Reply</button><button class="action" data-action="save-toggle" data-id="${esc(w.id)}" data-save-button="1" onclick="event.stopPropagation()">♡ Memory</button><button class="action" data-action="share" data-id="${esc(w.id)}" onclick="event.stopPropagation()">↗ Share</button>${mine?`<button class="action" data-action="edit" data-id="${esc(w.id)}" onclick="event.stopPropagation()">Edit</button><button class="action danger-text" data-action="delete" data-id="${esc(w.id)}" onclick="event.stopPropagation()">Delete</button>`:`<button class="action" data-action="report" data-id="${esc(w.id)}" title="Report possible rule violations, not disagreement" onclick="event.stopPropagation()">Report</button>`}</div></div></article>`}
  function loadCards(xs){return xs.map(w=>card(w,[])).join('')}
  async function hydrateSaveStates(xs){if(!client||!user||!xs.length)return;const ids=xs.map(x=>x.id);const r=await client.from('saves').select('whisper_id').eq('user_id',user.id).in('whisper_id',ids);if(r.error)return;const saved=new Set((r.data||[]).map(x=>x.whisper_id));xs.forEach(w=>{const b=document.querySelector(`button[data-save-button="1"][data-id="${CSS.escape(w.id)}"]`);if(b&&saved.has(w.id)){b.classList.add('active');b.textContent='♥ In Memory'}})}
async function hydrateFeedMedia(xs){if(!client||!xs.length)return;hydrateSaveStates(xs).catch(()=>{});const ids=xs.map(x=>x.id);const [r,tr]=await Promise.all([client.from('whisper_media').select('id,whisper_id,storage_path,mime_type,file_name,file_size,created_at').in('whisper_id',ids).order('created_at',{ascending:true}),client.from('whisper_tags').select('whisper_id,tag_type,tag_value').in('whisper_id',ids)]);if(!r.error){const by=new Map();(r.data||[]).forEach(m=>{if(!by.has(m.whisper_id))by.set(m.whisper_id,[]);by.get(m.whisper_id).push(m);mediaMetaCache.set(m.id,m)});xs.forEach(w=>{const slot=document.getElementById('media-'+w.id);if(slot){slot.dataset.mediaIds=(by.get(w.id)||[]).map(m=>m.id).join(',');slot.innerHTML=''}});const loadVisible=async idsToLoad=>{const ids2=[...new Set(idsToLoad.flatMap(id=>String(id).split(',')).filter(Boolean))].filter(id=>!mediaSignedCache.has(id));if(!ids2.length)return;const raw=ids2.map(id=>mediaMetaCache.get(id)).filter(Boolean);const signed=await signMedia(raw);signed.forEach(m=>mediaSignedCache.set(m.id,m));xs.forEach(w=>{const slot=document.getElementById('media-'+w.id);if(!slot)return;const mids=(slot.dataset.mediaIds||'').split(',').filter(Boolean);if(mids.some(id=>mediaSignedCache.has(id)))slot.innerHTML=mediaPreview(mids.map(id=>mediaSignedCache.get(id)).filter(Boolean))})};const eager=xs.slice(0,4).map(w=>document.getElementById('media-'+w.id)?.dataset.mediaIds||'').filter(Boolean);loadVisible(eager).catch(()=>{});if('IntersectionObserver' in window){const io=new IntersectionObserver(entries=>{entries.filter(e=>e.isIntersecting).forEach(e=>{io.unobserve(e.target);loadVisible([e.target.dataset.mediaIds||'']).catch(()=>{})})},{rootMargin:'500px'});xs.forEach(w=>{const slot=document.getElementById('media-'+w.id);if(slot&&slot.dataset.mediaIds)io.observe(slot)})}}if(!tr.error){const tb=new Map();(tr.data||[]).forEach(t=>{if(!tb.has(t.whisper_id))tb.set(t.whisper_id,[]);tb.get(t.whisper_id).push(t)});xs.forEach(w=>{const el=document.getElementById('tags-'+w.id);if(el)el.innerHTML=tagHTML(tb.get(w.id)||[])})}}
  async function home(){const target=location.hash||'#home';
    if(!user){
      app.innerHTML=`<section class="guest-home" aria-labelledby="guestTitle"><div class="guest-copy"><div class="guest-brandline"><h1 id="guestTitle"><span>Get</span> <em>rid</em></h1>${birdSketch()}</div><div class="guest-message"><p>When something weighs upon the mind,<br>And there is no one safe to tell,<br>There ought to be a quiet place<br>Where part of what we carry<br>May be laid down,<br>And left behind.</p></div><div class="guest-actions"><button class="btn" data-action="auth">Sign in</button><button class="btn ghost" data-action="switch-signup">Create account</button></div><div class="guest-trust">A quiet place for what you cannot safely carry alone.</div><div class="ai-tagline">100% AI-assisted platform</div></div></section>`;
      return;
    }
    app.innerHTML=shell('Home')+`<div class="feed-tabs"><a class="active" href="#for-you">For You</a><a href="#following">Following</a><a href="#timeline">Latest</a></div><div class="mobile-composer-trigger" data-action="compose"><div class="avatar">${avatarMarkup(currentProfile,profileName())}</div><span>What’s going through your mind?</span><button class="btn ghost" type="button">Whisper</button></div>`+composer()+`<div class="quick-links"><a class="btn ghost" href="#network">My Network</a><a class="btn ghost" href="#network-whispers">Network Whispers</a><a class="btn ghost" href="#popular">Popular Whispers</a><a class="btn ghost" href="#people">People to connect</a></div><div id="feed" class="feed"><div class="empty">Loading…</div></div>`;bindComposer();await renderForYouFeed(target);}
  async function searchWhispers(q){if(!client||!q)return[];const term=searchTerm(q);if(!term)return[];const [body,tags]=await Promise.all([client.from('whispers').select('*').eq('visibility','public').ilike('body',`%${term}%`).limit(50),client.from('whisper_tags').select('whisper_id,tag_type,tag_value').ilike('tag_value',`%${term}%`).limit(100)]);if(body.error)throw body.error;if(tags.error)throw tags.error;const byId=new Map((body.data||[]).map(w=>[w.id,{w,score:1}]));(tags.data||[]).forEach(t=>{if(byId.has(t.whisper_id))byId.get(t.whisper_id).score+=3;else byId.set(t.whisper_id,{w:null,score:3})});const missing=[...byId.values()].filter(x=>!x.w).map(x=>x);if(missing.length){const ids=missing.map((_,i)=>[...byId.entries()].filter(([id,v])=>!v.w)[i]?.[0]).filter(Boolean);if(ids.length){const r=await client.from('whispers').select('*').in('id',ids).eq('visibility','public');if(r.error)throw r.error;r.data?.forEach(w=>{const item=byId.get(w.id);if(item)item.w=w})}}const rows=[...byId.values()].filter(x=>x.w).sort((a,b)=>b.score-a.score||new Date(b.w.created_at)-new Date(a.w.created_at)).slice(0,30).map(x=>x.w);return decorateAuthors(rows)}
  function searchTerm(q){return String(q||'').trim().replace(/^#+/,'').trim().replace(/[%_,()]/g,' ').replace(/\s+/g,' ').slice(0,80)}
  async function globalSearch(q){if(!client)return{people:[],circles:[],whispers:[]};const term=searchTerm(q);if(!term)return{people:[],circles:[],whispers:[]};const pattern=`%${term}%`;const [pu,pd,pl,g,w,t]=await Promise.all([client.from('profiles').select('id,username,display_name,location_city,is_deactivated').eq('is_deactivated',false).ilike('username',pattern).limit(12),client.from('profiles').select('id,username,display_name,location_city,is_deactivated').eq('is_deactivated',false).ilike('display_name',pattern).limit(12),client.from('profiles').select('id,username,display_name,location_city,is_deactivated').eq('is_deactivated',false).ilike('location_city',pattern).limit(12),client.from('groups').select('id,name,description,location_city').or(`name.ilike.${pattern},description.ilike.${pattern},location_city.ilike.${pattern}`).limit(12),client.from('whispers').select('*').eq('visibility','public').ilike('body',pattern).limit(30),client.from('whisper_tags').select('whisper_id,tag_type,tag_value').ilike('tag_value',pattern).limit(50)]);for(const r of [pu,pd,pl,g,w,t])if(r.error)throw r.error;const peopleMap=new Map();[...(pu.data||[]),...(pd.data||[]),...(pl.data||[])].forEach(x=>peopleMap.set(x.id,x));const people=[...peopleMap.values()].slice(0,12);const whispers=[...(w.data||[])];const ids=new Set(whispers.map(x=>x.id));const tagIds=[...new Set((t.data||[]).map(x=>x.whisper_id))];if(tagIds.length){const r=await client.from('whispers').select('*').in('id',tagIds).eq('visibility','public');if(r.error)throw r.error;(r.data||[]).forEach(x=>{if(!ids.has(x.id)){whispers.push(x);ids.add(x.id)}})}return{people,circles:g.data||[],whispers:await decorateAuthors(whispers.slice(0,30))}}
  async function searchPage(query=''){const q=String(query||'').trim();app.innerHTML=shell('Search','Find people, Circles and public reflections')+`<div class="search-page"><form class="search-large" id="searchPageForm"><input id="searchPageInput" value="${esc(q)}" placeholder="Search people, Circles, Whispers, topics…" autocomplete="off"><button class="btn" type="submit">Search</button></form><div id="searchResults"><div class="empty">${q?'Searching…':'Type something to search.'}</div></div></div>`;if(!q)return;try{const r=await globalSearch(q);document.getElementById('searchResults').innerHTML=`<section class="search-section"><h2>People</h2>${r.people.length?r.people.map(p=>`<a class="search-result" href="#person/${esc(p.id)}"><div class="avatar small">${avatarMarkup(p,p.display_name||p.username)}</div><div><strong>${esc(p.display_name||p.username)}</strong><div class="hint">@${esc(p.username)}${p.location_city?' · '+esc(p.location_city):''}</div></div></a>`).join(''):'<div class="empty">No people found.</div>'}</section><section class="search-section"><h2>Circles</h2>${r.circles.length?r.circles.map(g=>`<a class="search-result" href="#circle/${esc(g.id)}"><div class="circle-icon">○</div><div><strong>${esc(g.name)}</strong><div class="hint">${esc(g.description||'')}</div></div></a>`).join(''):'<div class="empty">No Circles found.</div>'}</section><section class="search-section"><h2>Public Whispers</h2>${r.whispers.length?r.whispers.map(w=>card(w,[])).join(''):'<div class="empty">No public Whispers found.</div>'}</section>`;if(r.whispers.length)hydrateFeedMedia(r.whispers).catch(()=>{})}catch(e){document.getElementById('searchResults').innerHTML=`<div class="error">${esc(e.message)}</div>`}}
  async function explore(mode='latest',query=''){app.innerHTML=shell('Explore','Discover public reflections, media and common ground')+`<div class="tabs"><a class="${mode==='latest'?'active':''}" href="#explore">Latest</a><a class="${mode==='read'?'active':''}" href="#explore/read">Read</a><a class="${mode==='listen'?'active':''}" href="#explore/listen">Listen</a><a class="${mode==='see'?'active':''}" href="#explore/see">See</a><a class="${mode==='common'?'active':''}" href="#explore/common">Common</a></div><div id="feed" class="feed"><div class="empty">Loading…</div></div>`;try{let xs=query?await searchWhispers(query.replace(/^#+/,'')):await listPublic();if(mode==='listen'||mode==='see'){const ids=xs.map(x=>x.id);const mr=ids.length?await client.from('whisper_media').select('whisper_id,mime_type').in('whisper_id',ids):{data:[],error:null};if(!mr.error){const kinds=new Map();(mr.data||[]).forEach(m=>{if(!kinds.has(m.whisper_id))kinds.set(m.whisper_id,[]);kinds.get(m.whisper_id).push(m.mime_type)});xs=xs.filter(w=>(kinds.get(w.id)||[]).some(t=>mode==='listen'?t?.startsWith('audio/'):t?.startsWith('image/')||t?.startsWith('video/')))}}if(mode==='common'&&user){const tags=await client.from('whisper_tags').select('whisper_id,tag_type,tag_value').limit(500);const common=new Set((currentProfile?.interests||[]).map(x=>x.toLowerCase()));if(!tags.error)xs=xs.filter(w=>(tags.data||[]).some(t=>t.whisper_id===w.id&&common.has(String(t.tag_value).toLowerCase())))}document.getElementById('feed').innerHTML=xs.length?loadCards(xs):`<div class="empty">No matching Whispers yet.</div>`;if(xs.length)hydrateFeedMedia(xs).catch(()=>{})}catch(e){document.getElementById('feed').innerHTML=`<div class="error">${esc(e.message)}<br><button class="btn ghost" data-action="retry">Try again</button></div>`}}

  async function getFollowState(target){if(!client||!user||target===user.id)return false;const r=await client.from('follows').select('follower_id').eq('follower_id',user.id).eq('following_id',target).maybeSingle();if(r.error)throw r.error;return!!r.data}
  async function followUser(target){if(!user)throw new Error('Sign in to follow people.');if(target===user.id)throw new Error('You cannot follow yourself.');const r=await client.from('follows').insert({follower_id:user.id,following_id:target});if(r.error&&r.error.code!=='23505')throw r.error}
  async function unfollowUser(target){const r=await client.from('follows').delete().eq('follower_id',user.id).eq('following_id',target);if(r.error)throw r.error}
  async function followCounts(target){const r=await client.rpc('mindrid_follow_counts',{target});if(r.error)throw r.error;const row=Array.isArray(r.data)?r.data[0]:r.data;return{followers:Number(row?.followers||0),following:Number(row?.following||0)}}
  async function listPublicFeed(limit=40){const key='public:'+limit;const cached=feedCache[key];if(cached&&Date.now()-cached.at<15000)return cached.data;const r=await client.from('whispers').select('id,author_id,body,identity_mode,visibility,created_at,updated_at').eq('visibility','public').order('created_at',{ascending:false}).limit(limit);if(r.error)throw r.error;const xs=await decorateAuthors(r.data||[]);feedCache[key]={at:Date.now(),data:xs};return xs}
  async function getPersonalSignals(){if(!user)return{followed:new Set(),connected:new Set(),interests:new Set()};const [f,c]=await Promise.all([client.from('follows').select('following_id').eq('follower_id',user.id),client.from('connections').select('requester_id,addressee_id').or(`requester_id.eq.${user.id},addressee_id.eq.${user.id}`).eq('status','accepted')]);if(f.error)throw f.error;if(c.error)throw c.error;const followed=new Set((f.data||[]).map(x=>x.following_id));const connected=new Set((c.data||[]).map(x=>x.requester_id===user.id?x.addressee_id:x.requester_id));const interests=new Set((currentProfile?.interests||[]).map(x=>String(x).trim().toLowerCase()).filter(Boolean));return{followed,connected,interests}}
  async function renderForYouFeed(expectedHash=location.hash){if(location.hash!==expectedHash)return;const feed=document.getElementById('feed');if(!feed)return;feed.innerHTML='<div class="empty"><div class="loading-bar"></div>Finding reflections for you…</div>';try{const [xs,sig]=await Promise.all([listPublicFeed(50),getPersonalSignals()]);if(location.hash!==expectedHash)return;const tags=xs.length?await client.from('whisper_tags').select('whisper_id,tag_type,tag_value').in('whisper_id',xs.map(x=>x.id)):null;const tagMap=new Map();(tags?.data||[]).forEach(t=>{if(!tagMap.has(t.whisper_id))tagMap.set(t.whisper_id,[]);tagMap.get(t.whisper_id).push(String(t.tag_value).toLowerCase())});const now=Date.now();const scored=xs.map(w=>{let score=0;if(sig.followed.has(w.author_id))score+=8;if(sig.connected.has(w.author_id))score+=4;const its=tagMap.get(w.id)||[];score+=its.some(t=>sig.interests.has(t))?5:0;const age=(now-new Date(w.created_at).getTime())/3600000;score+=Math.max(0,3-age/24);return{w,score}}).sort((a,b)=>b.score-a.score||new Date(b.w.created_at)-new Date(a.w.created_at)).map(x=>x.w);feed.innerHTML=scored.length?loadCards(scored):'<div class="empty">No public Whispers yet. Be the first to leave a reflection.</div>';if(scored.length)hydrateFeedMedia(scored).catch(()=>{})}catch(e){if(feed)feed.innerHTML=`<div class="error">${esc(e.message)}<br><button class="btn ghost" data-action="retry">Try again</button></div>`}}
  async function timeline(){const target=location.hash;app.innerHTML=shell('Timeline','The public stream, in chronological order')+`<div id="feed" class="feed"><div class="empty">Loading…</div></div>`;try{const xs=await listPublicFeed(50);if(location.hash!==target)return;document.getElementById('feed').innerHTML=xs.length?loadCards(xs):'<div class="empty">Nothing public yet.</div>';if(xs.length)hydrateFeedMedia(xs).catch(()=>{})}catch(e){document.getElementById('feed').innerHTML=`<div class="error">${esc(e.message)}</div>`}}
  async function following(){if(!user){openAuth('signin');return}app.innerHTML=shell('Following')+`<div id="followingFeed" class="feed"><div class="empty">Loading…</div></div><section><div class="section-head"><h2>People you follow</h2></div><div id="followingPeople" class="people-list"></div></section>`;try{const r=await client.from('follows').select('following_id,created_at').eq('follower_id',user.id).order('created_at',{ascending:false});if(r.error)throw r.error;const ids=(r.data||[]).map(x=>x.following_id);const p=ids.length?await client.from('profiles').select('id,username,display_name,location_city,avatar_path').in('id',ids).eq('is_deactivated',false):{data:[],error:null};if(p.error)throw p.error;document.getElementById('followingPeople').innerHTML=(p.data||[]).map(x=>`<article class="person-card"><div class="avatar">${avatarMarkup(x,x.display_name||x.username)}</div><div class="person-main"><a href="#person/${esc(x.id)}"><strong>${esc(x.display_name||x.username)}</strong></a><div class="hint">@${esc(x.username||'')}</div></div><button class="btn ghost" data-action="unfollow" data-user-id="${esc(x.id)}">Following</button></article>`).join('')||'<div class="empty">You are not following anyone yet.</div>';if(!ids.length){document.getElementById('followingFeed').innerHTML='<div class="empty">Follow people to build your Following stream.</div>';return}const w=await client.from('whispers').select('*').in('author_id',ids).eq('visibility','public').order('created_at',{ascending:false}).limit(50);if(w.error)throw w.error;const xs=await decorateAuthors(w.data||[]);document.getElementById('followingFeed').innerHTML=xs.length?loadCards(xs):'<div class="empty">No recent public Whispers from people you follow.</div>';if(xs.length)hydrateFeedMedia(xs).catch(()=>{})}catch(e){document.getElementById('followingFeed').innerHTML=`<div class="error">${esc(e.message)}</div>`}}

  async function followers(){if(!user){openAuth('signin');return}app.innerHTML=shell('Followers','People who follow your reflections')+`<div id="followList" class="people-list"><div class="empty">Loading…</div></div>`;try{const r=await client.from('follows').select('follower_id,created_at').eq('following_id',user.id).order('created_at',{ascending:false});if(r.error)throw r.error;const ids=(r.data||[]).map(x=>x.follower_id);const p=ids.length?await client.from('profiles').select('id,username,display_name,location_city,avatar_path').in('id',ids).eq('is_deactivated',false):{data:[],error:null};if(p.error)throw p.error;const mine=ids.length?await client.from('follows').select('following_id').eq('follower_id',user.id).in('following_id',ids):{data:[],error:null};if(mine.error)throw mine.error;const followingSet=new Set((mine.data||[]).map(x=>x.following_id));document.getElementById('followList').innerHTML=(p.data||[]).map(x=>`<article class="person-card"><div class="avatar">${avatarMarkup(x,x.display_name||x.username)}</div><div class="person-main"><a href="#person/${esc(x.id)}"><strong>${esc(x.display_name||x.username)}</strong></a><div class="hint">@${esc(x.username||'')}</div></div>${user.id===x.id?'':followingSet.has(x.id)?`<button class="btn ghost" data-action="unfollow" data-user-id="${esc(x.id)}">Following</button>`:`<button class="btn ghost" data-action="follow" data-user-id="${esc(x.id)}">Follow</button>`}</article>`).join('')||'<div class="empty">No followers yet.</div>'}catch(e){document.getElementById('followList').innerHTML=`<div class="error">${esc(e.message)}</div>`}}
