  async function community(){app.innerHTML=shell('Community','Find the communities and shared spaces around reflections')+`<section class="prose-hero"><span class="eyebrow">Community</span><h2>Reflections meet people here.</h2><p>Explore Circles, follow people whose reflections resonate with you, and enter conversations without losing the reflection itself.</p></section><div class="quick-links"><a class="btn" href="#groups">Circles</a><a class="btn ghost" href="#people">People</a><a class="btn ghost" href="#following">Following</a><a class="btn ghost" href="#followers">Followers</a></div><div id="communityCircles" class="group-list"><div class="empty">Loading Circles…</div></div>`;try{const r=await client.from('groups').select('id,name,description,location_city').order('created_at',{ascending:false}).limit(12);if(r.error)throw r.error;document.getElementById('communityCircles').innerHTML=(r.data||[]).map(g=>`<article class="group-card"><div><h3><a href="#circle/${esc(g.id)}">${esc(g.name)}</a></h3><p>${esc(g.description||'')}</p></div><a class="btn ghost" href="#circle/${esc(g.id)}">Open</a></article>`).join('')||'<div class="empty">No communities yet.</div>'}catch(e){document.getElementById('communityCircles').innerHTML=`<div class="error">${esc(e.message)}</div>`}}
