  async function my(){if(!user){app.innerHTML=shell('My Whispers')+`<div class="auth-box"><h1>Your Whispers</h1><p>Sign in to keep your reflections across devices and join conversations.</p><button class="btn" data-action="auth">Sign in / Create account</button></div>`;return}app.innerHTML=shell('My Whispers','Everything you have left here')+`<div id="feed" class="feed"><div class="empty">Loading…</div></div>`;try{const xs=await listMine();document.getElementById('feed').innerHTML=xs.length?loadCards(xs):`<div class="empty">You haven't left a Whisper yet.</div>`;if(xs.length)hydrateFeedMedia(xs).catch(()=>{} )}catch(e){document.getElementById('feed').innerHTML=`<div class="error">${esc(e.message)}<br><button class="btn ghost" data-action="retry">Try again</button></div>`}}
  async function openWhisper(id){let w=null;try{w=await getWhisper(id);if(user&&!w){const mine=await listMine();w=mine.find(x=>x.id===id)}}catch(e){}if(!w){toast('That Whisper is unavailable.','error');return}currentWhisper=w;if(user)client.from('whisper_history').upsert({user_id:user.id,whisper_id:w.id,viewed_at:new Date().toISOString()},{onConflict:'user_id,whisper_id'}).then(()=>{}).catch(()=>{});app.innerHTML=`<div class="page-head"><a href="#${w.author_id===user?.id?'my':'home'}" style="color:var(--accent);text-decoration:none">← Back</a></div><article class="thread"><div class="whisper-meta"><span class="name">${w.identity_mode==='real'?esc(w.author_id===user?.id?profileName():(w.author_profile?.display_name||w.author_profile?.username||'Someone')):'Anonymous'}</span><span class="time">· ${fmt(w.created_at)}${w.updated_at!==w.created_at?' · edited':''}</span></div><div class="thread-body">${esc(w.body)}</div><div id="threadTags"><div class="empty">Loading tags…</div></div><div id="threadMedia"><div class="empty">Loading media…</div></div><div class="thread-actions"><button class="action" data-action="like" data-id="${esc(w.id)}">♡ Like</button><button class="action" data-action="save-toggle" data-id="${esc(w.id)}">♡ Memory</button><button class="action" data-action="share" data-id="${esc(w.id)}">↗ Share</button>${w.author_id===user?.id?`<button class="action" data-action="edit" data-id="${esc(w.id)}">Edit</button><button class="action danger-text" data-action="delete" data-id="${esc(w.id)}">Delete</button>`:`<button class="action" data-action="report" data-id="${esc(w.id)}" title="Report possible rule violations, not disagreement">Report</button>`}</div></article><section class="comments"><h3>Replies</h3><div id="commentArea"><div class="empty">Loading replies…</div></div></section>`;const mediaPromise=listMedia('whisper',id).catch(()=>[]);const commentsPromise=(client&&w.visibility!=='private')?renderComments(w.id):Promise.resolve();const media=await mediaPromise;const slot=document.getElementById('threadMedia');if(slot)slot.innerHTML=mediaPreview(media);const tg=await client.from('whisper_tags').select('*').eq('whisper_id',id);const tagSlot=document.getElementById('threadTags');if(tagSlot)tagSlot.innerHTML=tagHTML(tg.error?[]:(tg.data||[]));await commentsPromise;const match=(location.hash.split('?')[1]||'').match(/(?:^|&)comment=([^&]+)/);if(match){setTimeout(()=>document.getElementById('comment-'+decodeURIComponent(match[1]))?.scrollIntoView({behavior:'smooth',block:'center'}),60)}}
  function commentHTML(c,all,media=[],reactionMap=new Map()){const name=c.profiles?.display_name||c.profiles?.username||'Someone';const kids=all.filter(x=>x.parent_comment_id===c.id);const mine=c.author_id===user?.id;const r=reactionMap.get(c.id)||{like:0,dislike:0,mine:null};return `<div class="comment ${c.parent_comment_id?'reply':''}" id="comment-${esc(c.id)}"><div class="comment-meta"><span class="comment-author">${esc(name)}</span> · ${fmt(c.created_at)}${c.updated_at!==c.created_at?' · edited':''}</div><div class="comment-body">${esc(c.body)}</div>${mediaPreview(media.filter(m=>m.comment_id===c.id))}<div class="comment-actions">${user?`<button class="action ${r.mine==='like'?'active':''}" data-action="comment-reaction" data-reaction="like" data-comment="${esc(c.id)}">♥ <span class="comment-reaction-count" data-reaction="like">${r.like}</span></button><button class="action ${r.mine==='dislike'?'active':''}" data-action="comment-reaction" data-reaction="dislike" data-comment="${esc(c.id)}">👎 <span class="comment-reaction-count" data-reaction="dislike">${r.dislike}</span></button><button class="action" data-action="reply-comment" data-comment="${esc(c.id)}">↩ Reply</button>`:''}<button class="action" data-action="share-comment" data-whisper="${esc(c.whisper_id)}" data-comment="${esc(c.id)}">↗ Share</button>${mine?`<button class="action" data-action="edit-comment" data-comment="${esc(c.id)}">Edit</button><button class="action danger-text" data-action="delete-comment" data-comment="${esc(c.id)}">Delete</button>`:user?`<button class="action" title="Report possible rule violations, not disagreement" data-action="report-comment" data-comment="${esc(c.id)}">Report</button>`:''}</div>${kids.map(x=>commentHTML(x,all,media,reactionMap)).join('')}</div>`}
  async function renderComments(id){const el=document.getElementById('commentArea');try{const cs=await listComments(id);let media=[];let reactions=[];if(client&&cs.length){const [mr,rr]=await Promise.all([client.from('comment_media').select('*').in('comment_id',cs.map(c=>c.id)),loadCommentReactions(cs.map(c=>c.id))]);if(!mr.error)media=await signMedia(mr.data||[]);reactions=rr}const reactionMap=new Map();reactions.forEach(x=>{const r=reactionMap.get(x.comment_id)||{like:0,dislike:0,mine:null};r[x.reaction]=(r[x.reaction]||0)+1;if(x.user_id===user?.id)r.mine=x.reaction;reactionMap.set(x.comment_id,r)});el.innerHTML=(user?`<form class="reply-form" id="replyForm"><input id="replyInput" maxlength="3000" placeholder="Write a reply…"><button class="btn">Reply</button></form>${attachmentPicker('reply')}`:'<div class="notice">Sign in to reply.</div>')+(cs.length?cs.map(c=>!c.parent_comment_id?commentHTML(c,cs,media,reactionMap):'').join(''):'<div class="empty">No replies yet. Be the first to add one.</div>');if(user)bindMediaPicker('reply');}catch(e){el.innerHTML=`<div class="error">${esc(e.message)}<br><button class="btn ghost" data-action="retry-comments">Try again</button></div>`}}
    function tagHTML(tags){if(!tags?.length)return'';return `<div class="tag-row">${tags.map(t=>`<span class="tag-pill">${esc(t.tag_type)}: ${esc(t.tag_value)}</span>`).join('')}</div>`}
  function collectTags(){const base=[['location','tagLocation'],['feeling','tagFeeling'],['idea','tagIdea'],['vibe','tagVibe']].map(([type,id])=>({tag_type:type,tag_value:(composerEl('#'+id)?.value||'').trim()})).filter(x=>x.tag_value);const body=composerEl('#whisperText')?.value||'';const mentions=[...body.matchAll(/@([a-zA-Z0-9_]{2,30})/g)].map(m=>m[1].toLowerCase());return base.concat([...new Set(mentions)].map(v=>({tag_type:'person',tag_value:v})).filter(x=>x.tag_value))}
  async function saveTags(whisperId,tags){if(!client||!tags.length)return;const r=await client.from('whisper_tags').insert(tags.map(t=>({...t,whisper_id:whisperId})));if(r.error)throw r.error}
  async function searchProfiles(q){if(!client||!q.trim())return[];const x=searchTerm(q);if(!x)return[];const pattern=`%${x}%`;const [u,d]=await Promise.all([client.from('profiles').select('id,username,display_name,avatar_path,location_city,location_country,interests').ilike('username',pattern).neq('id',user?.id||'00000000-0000-0000-0000-000000000000').eq('is_deactivated',false).limit(8),client.from('profiles').select('id,username,display_name,avatar_path,location_city,location_country,interests').ilike('display_name',pattern).neq('id',user?.id||'00000000-0000-0000-0000-000000000000').eq('is_deactivated',false).limit(8)]);if(u.error)throw u.error;if(d.error)throw d.error;const map=new Map([...(u.data||[]),...(d.data||[])].map(p=>[p.id,p]));return [...map.values()].slice(0,8)}
  function profileSuggestionHTML(p,type='message'){return `<button type="button" class="suggestion" data-action="${type==='mention'?'mention-suggestion':'profile-suggestion'}" data-user="${esc(p.username)}"><span class="avatar small">${esc((p.display_name||p.username||'P')[0].toUpperCase())}</span><span><strong>${esc(p.display_name||p.username)}</strong><small>@${esc(p.username)}${p.location_city?` · ${esc(p.location_city)}`:''}</small></span></button>`}
  async function searchNetworkProfiles(q){if(!client||!user)return[];const x=searchTerm(q);if(!x)return[];const c=await client.from('connections').select('requester_id,addressee_id').or(`requester_id.eq.${user.id},addressee_id.eq.${user.id}`).eq('status','accepted');if(c.error)throw c.error;const ids=[...new Set((c.data||[]).map(v=>v.requester_id===user.id?v.addressee_id:v.requester_id))];if(!ids.length)return[];const pattern=`%${x}%`;const [u,d]=await Promise.all([client.from('profiles').select('id,username,display_name,avatar_path,location_city').in('id',ids).ilike('username',pattern).eq('is_deactivated',false).limit(8),client.from('profiles').select('id,username,display_name,avatar_path,location_city').in('id',ids).ilike('display_name',pattern).eq('is_deactivated',false).limit(8)]);if(u.error)throw u.error;if(d.error)throw d.error;const map=new Map([...(u.data||[]),...(d.data||[])].map(p=>[p.id,p]));return [...map.values()].slice(0,8)}
