  async function ensureAAL2(){const f=await client.auth.mfa.listFactors();if(f.error)throw f.error;const factor=(f.data?.totp||[]).find(x=>x.status==='verified');if(!factor)return;const aal=await client.auth.mfa.getAuthenticatorAssuranceLevel();if(aal.error)throw aal.error;if(aal.data?.currentLevel==='aal2')return;const ch=await client.auth.mfa.challenge({factorId:factor.id});if(ch.error)throw ch.error;const code=prompt('Enter your six-digit authenticator code to continue:');if(!code)throw new Error('Two-factor authentication is required for this action.');const v=await client.auth.mfa.verify({factorId:factor.id,challengeId:ch.data.id,code:code.trim()});if(v.error)throw v.error}
